#include <assert.h>
#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <zephyr/data/json.h>
#include <zephyr/sys/printk.h>
#include <zephyr/sys/util.h>
#include <zephyr/types.h>

struct token {
	enum json_tokens type;
	char *start;
	char *end;
};

struct lexer {
	void *(*state)(struct lexer *lex);
	char *start;
	char *pos;
	char *end;
	struct token tok;
};

struct json_obj {
	struct lexer lex;
};

struct json_obj_key_value {
	const char *key;
	size_t key_len;
	struct token value;
};

static bool lexer_consume(struct lexer *lex, struct token *tok,
			  enum json_tokens empty_token)
{
	if (lex->tok.type == empty_token) {
		return false;
	}

	*tok = lex->tok;
	lex->tok.type = empty_token;

	return true;
}

static void *lexer_json(struct lexer *lex);

static void emit(struct lexer *lex, enum json_tokens token)
{
	lex->tok.type = token;
	lex->tok.start = lex->start;
	lex->tok.end = lex->pos;
	lex->start = lex->pos;
}

static int next(struct lexer *lex)
{
	if (lex->pos >= lex->end) {
		lex->pos = lex->end + 1;

		return '\0';
	}

	return *lex->pos++;
}

static void ignore(struct lexer *lex)
{
	lex->start = lex->pos;
}

static void backup(struct lexer *lex)
{
	lex->pos--;
}

static int peek(struct lexer *lex)
{
	int chr = next(lex);

	backup(lex);

	return chr;
}

static void *lexer_string(struct lexer *lex)
{
	ignore(lex);

	while (true) {
		int chr = next(lex);

		if (chr == '\0') {
			emit(lex, JSON_TOK_ERROR);
			return NULL;
		}

		if (chr == '\\') {
			switch (next(lex)) {
			case '"':
			case '\\':
			case '/':
			case 'b':
			case 'f':
			case 'n':
			case 'r':
			case 't':
				break;
			case 'u':
				if (isxdigit(next(lex)) == 0) {
					goto error;
				}

				if (isxdigit(next(lex)) == 0) {
					goto error;
				}

				if (isxdigit(next(lex)) == 0) {
					goto error;
				}

				if (isxdigit(next(lex)) == 0) {
					goto error;
				}

				break;
			default:
				goto error;
			}
		}

		if (chr == '"') {
			backup(lex);
			emit(lex, JSON_TOK_STRING);

			next(lex);
			ignore(lex);

			return lexer_json;
		}
	}

error:
	emit(lex, JSON_TOK_ERROR);
	return NULL;
}

static int accept_run(struct lexer *lex, const char *run)
{
	for (; *run; run++) {
		if (next(lex) != *run) {
			return -EINVAL;
		}
	}

	return 0;
}

static void *lexer_boolean(struct lexer *lex)
{
	backup(lex);

	switch (next(lex)) {
	case 't':
		if (!accept_run(lex, "rue")) {
			emit(lex, JSON_TOK_TRUE);
			return lexer_json;
		}
		break;
	case 'f':
		if (!accept_run(lex, "alse")) {
			emit(lex, JSON_TOK_FALSE);
			return lexer_json;
		}
		break;
	}

	emit(lex, JSON_TOK_ERROR);
	return NULL;
}

static void *lexer_null(struct lexer *lex)
{
	backup(lex);

	if (!accept_run(lex, "null")) {
		emit(lex, JSON_TOK_NULL);
		return lexer_json;
	}

	emit(lex, JSON_TOK_ERROR);
	return NULL;
}

static void *lexer_number(struct lexer *lex)
{
	bool has_dot = false;
	bool has_exp = false;
	bool has_exp_sign = false;
	bool has_digits = false;

	while (true) {
		int chr = next(lex);

		switch (chr) {
		case '.':
			if (has_dot || has_exp) {
				goto error;
			}
			has_dot = true;
			has_digits = false;
			break;
		case 'e':
		case 'E':
			if (has_exp) {
				goto error;
			}
			has_exp = true;
			has_digits = false;
			break;
		case '+':
		case '-':
			if (!has_exp || has_exp_sign || has_digits) {
				goto error;
			}
			has_exp_sign = true;
			break;
		case '0':
		case '1':
		case '2':
		case '3':
		case '4':
		case '5':
		case '6':
		case '7':
		case '8':
		case '9':
			has_digits = true;
			break;
		default:
			if (!has_digits) {
				goto error;
			}
			backup(lex);
			emit(lex, (has_dot || has_exp) ? JSON_TOK_FLOAT : JSON_TOK_NUMBER);
			return lexer_json;
		}
	}

error:
	emit(lex, JSON_TOK_ERROR);
	return NULL;
}

static void *lexer_json(struct lexer *lex)
{
	while (true) {
		int chr = next(lex);

		switch (chr) {
		case '\0':
			emit(lex, JSON_TOK_EOF);
			return NULL;
		case '}':
		case '{':
		case '[':
		case ']':
		case ',':
		case ':':
			emit(lex, (enum json_tokens)chr);
			return lexer_json;
		case '"':
			return lexer_string;
		case 'n':
			return lexer_null;
		case 't':
		case 'f':
			return lexer_boolean;
		case '-':
			if (isdigit(peek(lex))) {
				return lexer_number;
			}

			__fallthrough;
		default:
			if (isspace(chr)) {
				ignore(lex);
				continue;
			}

			if (isdigit(chr)) {
				return lexer_number;
			}

			emit(lex, JSON_TOK_ERROR);
			return NULL;
		}
	}
}

static void lexer_next(struct lexer *lex, struct token *tok)
{
	while (lex->state) {
		if (lexer_consume(lex, tok, JSON_TOK_NONE)) {
			return;
		}

		lex->state = lex->state(lex);
	}

	lexer_consume(lex, tok, JSON_TOK_EOF);
}

static void lexer_init(struct lexer *lex, char *data, size_t len)
{
	lex->state = lexer_json;
	lex->start = data;
	lex->pos = data;
	lex->end = data + len;
	lex->tok.type = JSON_TOK_NONE;
}

static int obj_init(struct json_obj *json, char *data, size_t len)
{
	struct token tok;

	lexer_init(&json->lex, data, len);

	lexer_next(&json->lex, &tok);
	if (tok.type != JSON_TOK_OBJECT_START) {
		return -EINVAL;
	}

	return 0;
}

static int element_token(enum json_tokens token)
{
	switch (token) {
	case JSON_TOK_OBJECT_START:
	case JSON_TOK_LIST_START:
	case JSON_TOK_STRING:
	case JSON_TOK_STRING_BUF:
	case JSON_TOK_NUMBER:
	case JSON_TOK_FLOAT:
	case JSON_TOK_FLOAT_FP:
	case JSON_TOK_DOUBLE_FP:
	case JSON_TOK_TRUE:
	case JSON_TOK_FALSE:
	case JSON_TOK_NULL:
		return 0;
	default:
		return -EINVAL;
	}
}

static int obj_next(struct json_obj *json,
		    struct json_obj_key_value *kv)
{
	struct token tok;

	lexer_next(&json->lex, &tok);
	if (tok.type == JSON_TOK_COMMA) {
		lexer_next(&json->lex, &tok);
	}

	if (tok.type == JSON_TOK_OBJECT_END) {
		kv->key = NULL;
		kv->key_len = 0;
		kv->value = tok;

		return 0;
	}

	if (tok.type != JSON_TOK_STRING) {
		return -EINVAL;
	}

	kv->key = tok.start;
	kv->key_len = (size_t)(tok.end - tok.start);

	lexer_next(&json->lex, &tok);
	if (tok.type != JSON_TOK_COLON) {
		return -EINVAL;
	}

	lexer_next(&json->lex, &kv->value);

	return element_token(kv->value.type);
}

static int arr_next(struct json_obj *json, struct token *value)
{
	lexer_next(&json->lex, value);

	if (value->type == JSON_TOK_COMMA) {
		lexer_next(&json->lex, value);
	}

	if (value->type == JSON_TOK_LIST_END) {
		return 0;
	}

	return element_token(value->type);
}

static int decode_num(const struct token *token, int32_t *num)
{
	/* FIXME: strtol() is not available in minimal libc */
	char *endptr;
	char prev_end;

	prev_end = *token->end;
	*token->end = '\0';

	errno = 0;
	*num = strtol(token->start, &endptr, 10);

	*token->end = prev_end;

	if (errno != 0) {
		return -errno;
	}

	if (*endptr != '\0') {
		return -EINVAL;
	}

	return 0;
}

static int decode_int64(const struct token *token, int64_t *num)
{
	char *endptr;
	char prev_end;

	prev_end = *token->end;
	*token->end = '\0';

	errno = 0;
	*num = strtoll(token->start, &endptr, 10);

	*token->end = prev_end;

	if (errno != 0) {
		return -errno;
	}

	if (*endptr != '\0') {
		return -EINVAL;
	}

	return 0;
}

static int decode_uint64(const struct token *token, uint64_t *num)
{
	char *endptr;
	char prev_end;

	if (*token->start == '-') {
		return -EINVAL;
	}

	prev_end = *token->end;
	*token->end = '\0';

	errno = 0;
	*num = strtoull(token->start, &endptr, 10);

	*token->end = prev_end;

	if (errno != 0) {
		return -errno;
	}

	if (*endptr != '\0') {
		return -EINVAL;
	}

	return 0;
}

static int decode_uint32(const struct token *token, uint32_t *num)
{
	uint64_t num64;
	int err = decode_uint64(token, &num64);

	if (err != 0) {
		return err;
	}

	if (num64 > UINT32_MAX) {
		return -EINVAL;
	}

	*num = num64;

	return 0;
}

#ifdef CONFIG_JSON_LIBRARY_FP_SUPPORT
static int decode_float(const struct token *token, float *num)
{
	char *endptr;
	char prev_end;

	prev_end = *token->end;
	*token->end = '\0';

	errno = 0;
	*num = strtof(token->start, &endptr);

	*token->end = prev_end;

	if (errno != 0) {
		return -errno;
	}

	if (*endptr != '\0') {
		return -EINVAL;
	}

	return 0;
}

static int decode_double(const struct token *token, double *num)
{
	char *endptr;
	char prev_end;

	prev_end = *token->end;
	*token->end = '\0';

	errno = 0;
	*num = strtod(token->start, &endptr);

	*token->end = prev_end;

	if (errno != 0) {
		return -errno;
	}

	if (*endptr != '\0') {
		return -EINVAL;
	}

	return 0;
}
#endif /* CONFIG_JSON_LIBRARY_FP_SUPPORT */

static bool equivalent_types(enum json_tokens type1, enum json_tokens type2)
{
	if (type1 == JSON_TOK_TRUE || type1 == JSON_TOK_FALSE) {
		return type2 == JSON_TOK_TRUE || type2 == JSON_TOK_FALSE;
	}

	if (type1 == JSON_TOK_NUMBER && type2 == JSON_TOK_FLOAT) {
		return true;
	}

	if ((type1 == JSON_TOK_NUMBER || type1 == JSON_TOK_FLOAT) &&
	    (type2 == JSON_TOK_FLOAT_FP || type2 == JSON_TOK_DOUBLE_FP ||
	     type2 == JSON_TOK_INT64 || type2 == JSON_TOK_UINT64 ||
	     type2 == JSON_TOK_INT || type2 == JSON_TOK_UINT)) {
		return true;
	}

	if (type1 == JSON_TOK_STRING && type2 == JSON_TOK_STRING_BUF) {
		return true;
	}

	return type1 == type2;
}

static int obj_parse(struct json_obj *obj,
		     const struct json_obj_descr *descr, size_t descr_len,
		     void *val);
static int arr_parse(struct json_obj *obj,
		     const struct json_obj_descr *elem_descr,
		     size_t max_elements, void *field, void *val);
static int arr_data_parse(struct json_obj *json, struct token *value);

static inline size_t align_shift(enum json_tokens type)
{
	if (type == JSON_TOK_OBJECT_START) {
		return LOG2(sizeof(void *));
	}
	return 0;
}

static ptrdiff_t get_elem_size(const struct json_obj_descr *descr)
{
	switch (descr->type) {
	case JSON_TOK_NUMBER:
	case JSON_TOK_INT:
		return sizeof(int32_t);
	case JSON_TOK_UINT:
		return sizeof(uint32_t);
	case JSON_TOK_INT64:
		return sizeof(int64_t);
	case JSON_TOK_UINT64:
		return sizeof(uint64_t);
#ifdef CONFIG_JSON_LIBRARY_FP_SUPPORT
	case JSON_TOK_FLOAT_FP:
		return sizeof(float);
	case JSON_TOK_DOUBLE_FP:
		return sizeof(double);
#endif
	case JSON_TOK_STRING:
	case JSON_TOK_FLOAT:
		return sizeof(char *);
	case JSON_TOK_STRING_BUF:
		return descr->field.size;
	case JSON_TOK_TRUE:
	case JSON_TOK_FALSE:
		return sizeof(bool);
	case JSON_TOK_LIST_START:
		return descr->array.n_elements * get_elem_size(descr->array.element_descr);
	case JSON_TOK_OBJECT_START:
	{
		ptrdiff_t total = 0;
		size_t i;

		for (i = 0; i < descr->object.sub_descr_len; i++) {
			ptrdiff_t s = get_elem_size(&descr->object.sub_descr[i]);

			total += ROUND_UP(s, 1 << descr->align_shift);
		}

		return total > 0 ? total : 0;
	}
	case JSON_TOK_OBJ_ARRAY:
		return descr->field.size;
	case JSON_TOK_ENCODED_OBJ:
		return sizeof(char *);
	case JSON_TOK_MIXED_ARR:
		return 0;
	default:
		return -EINVAL;
	}
}

static void unescape(char *str)
{
	char *out = str;
	char *in = str;

	while (*in) {
		if (*in == '\\') {
			in++;
			switch (*in) {
			case '"':
				*out++ = '"';
				break;
			case '\\':
				*out++ = '\\';
				break;
			case '/':
				*out++ = '/';
				break;
			case 'b':
				*out++ = '\b';
				break;
			case 'f':
				*out++ = '\f';
				break;
			case 'n':
				*out++ = '\n';
				break;
			case 'r':
				*out++ = '\r';
				break;
			case 't':
				*out++ = '\t';
				break;
			case 'u':
				*out++ = '\\';
				*out++ = 'u';
				for (int i = 0; i < 4 && in[1]; i++) {
					*out++ = *++in;
				}
				break;
			default:
				break;
			}
			in++;
		} else {
			*out++ = *in++;
		}
	}

	*out = '\0';
}

static int decode_value(struct json_obj *obj,
			const struct json_obj_descr *descr,
			struct token *value, void *field, void *val)
{
	if (descr->type == JSON_TOK_ENCODED_OBJ) {
		if (value->type != JSON_TOK_OBJECT_START &&
		    value->type != JSON_TOK_LIST_START) {
			return -EINVAL;
		}
		int ret = arr_data_parse(obj, value);

		if (ret < 0) {
			return ret;
		}
		*value->end = '\0';
		*(char **)field = value->start;
		return 0;
	}

	if (!equivalent_types(value->type, descr->type)) {
		return -EINVAL;
	}

	switch (descr->type) {
	case JSON_TOK_OBJECT_START:
		return obj_parse(obj, descr->object.sub_descr,
				 descr->object.sub_descr_len,
				 field);
	case JSON_TOK_LIST_START:
		return arr_parse(obj, descr->array.element_descr,
				 descr->array.n_elements, field, val);
	case JSON_TOK_FALSE:
	case JSON_TOK_TRUE:
	{
		bool *v = field;

		*v = value->type == JSON_TOK_TRUE;

		return 0;
	}
	case JSON_TOK_NUMBER:
	{
		int32_t *num = field;

		return decode_num(value, num);
	}
	case JSON_TOK_INT:
	{
		int64_t num64;
		int err = decode_int64(value, &num64);

		if (err != 0) {
			return err;
		}

		switch (descr->field.size) {
		case sizeof(int8_t):
		{
			if (num64 < INT8_MIN || num64 > INT8_MAX) {
				return -EINVAL;
			}

			int8_t *num = field;

			*num = num64;
			return 0;
		}
		case sizeof(int16_t):
		{
			if (num64 < INT16_MIN || num64 > INT16_MAX) {
				return -EINVAL;
			}

			int16_t *num = field;

			*num = num64;
			return 0;
		}
		case sizeof(int32_t):
		{
			if (num64 < INT32_MIN || num64 > INT32_MAX) {
				return -EINVAL;
			}

			int32_t *num = field;

			*num = num64;
			return 0;
		}
		case sizeof(int64_t):
		{
			int64_t *num = field;

			*num = num64;
			return 0;
		}
		default:
			return -EINVAL;
		}
	}
	case JSON_TOK_UINT:
	{
		uint64_t num64;
		int err = decode_uint64(value, &num64);

		if (err != 0) {
			return err;
		}

		switch (descr->field.size) {
		case sizeof(uint8_t):
		{
			if (num64 > UINT8_MAX) {
				return -EINVAL;
			}

			uint8_t *num = field;

			*num = num64;
			return 0;
		}
		case sizeof(uint16_t):
		{
			if (num64 > UINT16_MAX) {
				return -EINVAL;
			}

			uint16_t *num = field;

			*num = num64;
			return 0;
		}
		case sizeof(uint32_t):
		{
			if (num64 > UINT32_MAX) {
				return -EINVAL;
			}

			uint32_t *num = field;

			*num = num64;
			return 0;
		}
		case sizeof(uint64_t):
		{
			uint64_t *num = field;

			*num = num64;
			return 0;
		}
		default:
			return -EINVAL;
		}
	}
	case JSON_TOK_INT64:
	{
		int64_t *num = field;

		return decode_int64(value, num);
	}
	case JSON_TOK_UINT64:
	{
		uint64_t *num = field;

		return decode_uint64(value, num);
	}
#ifdef CONFIG_JSON_LIBRARY_FP_SUPPORT
	case JSON_TOK_FLOAT_FP:
	{
		float *num = field;

		return decode_float(value, num);
	}
	case JSON_TOK_DOUBLE_FP:
	{
		double *num = field;

		return decode_double(value, num);
	}
#endif /* CONFIG_JSON_LIBRARY_FP_SUPPORT */
	case JSON_TOK_STRING:
	case JSON_TOK_FLOAT:
	{
		char **str = field;

		*value->end = '\0';
		if (descr->type == JSON_TOK_STRING) {
			unescape(value->start);
		}
		*str = value->start;

		return 0;
	}
	case JSON_TOK_STRING_BUF:
	{
		char *str = field;

		*value->end = '\0';
		unescape(value->start);
		size_t len = strlen(value->start);

		if (len >= descr->field.size) {
			return -ENOMEM;
		}

		memcpy(str, value->start, len);
		str[len] = '\0';

		return 0;
	}
	default:
		return -EINVAL;
	}
}

static ptrdiff_t get_elem_offset(const struct json_obj_descr *descr, size_t index)
{
	if (descr->type == JSON_TOK_OBJ_ARRAY) {
		return index * descr->field.size;
	}

	return index * get_elem_size(descr);
}

static int arr_data_parse(struct json_obj *json, struct token *value)
{
	bool empty_element = true;
	int err = 0;
	struct token tok;
	unsigned int depth = 1;
	char *end = value->end;

	while (depth > 0) {
		lexer_next(&json->lex, &tok);

		switch (tok.type) {
		case JSON_TOK_OBJECT_START:
		case JSON_TOK_LIST_START:
			depth += 1;
			empty_element = true;
			break;
		case JSON_TOK_OBJECT_END:
		case JSON_TOK_LIST_END:
			depth -= 1;
			empty_element = false;
			break;
		case JSON_TOK_COMMA:
			if (empty_element) {
				err = -EINVAL;
				goto out;
			}
			empty_element = true;
			break;
		case JSON_TOK_COLON:
		case JSON_TOK_STRING:
		case JSON_TOK_STRING_BUF:
		case JSON_TOK_NUMBER:
		case JSON_TOK_FLOAT:
		case JSON_TOK_FLOAT_FP:
		case JSON_TOK_DOUBLE_FP:
		case JSON_TOK_TRUE:
		case JSON_TOK_FALSE:
		case JSON_TOK_NULL:
			empty_element = false;
			break;
		default:
			err = -EINVAL;
			goto out;
		}
		end = tok.end;
	}
	value->end = end;

out:
	return err;
}

static int arr_parse(struct json_obj *obj,
		     const struct json_obj_descr *elem_descr,
		     size_t max_elements, void *field, void *val)
{
	ptrdiff_t elem_size;
	size_t *elements = (void *)((char *)val + elem_descr->offset);

	if (elem_descr->type == JSON_TOK_OBJ_ARRAY) {
		elem_size = elem_descr->field.size;
		elem_descr = elem_descr->object.sub_descr;
	} else {
		elem_size = get_elem_size(elem_descr);
	}

	assert(elem_size > 0);

	*elements = 0;

	while (*elements < max_elements) {
		void *ptr = (char *)field + elem_size * (*elements);
		struct token value;

		if (arr_next(obj, &value) < 0) {
			return -EINVAL;
		}

		if (value.type == JSON_TOK_LIST_END) {
			return 0;
		}

		int ret = decode_value(obj, elem_descr, &value, ptr, val);
		if (ret < 0) {
			return ret;
		}

		(*elements)++;
	}

	struct token value;

	if (arr_next(obj, &value) < 0) {
		return -EINVAL;
	}

	if (value.type == JSON_TOK_LIST_END) {
		return 0;
	}

	return -ENOSPC;
}

static int obj_parse(struct json_obj *obj, const struct json_obj_descr *descr,
		     size_t descr_len, void *val)
{
	struct json_obj_key_value kv;
	int64_t decoded_fields = 0;
	size_t i;
	int ret;

	while (!obj_next(obj, &kv)) {
		if (kv.value.type == JSON_TOK_OBJECT_END) {
			return decoded_fields;
		}

		for (i = 0; i < descr_len; i++) {
			void *decode_field = (char *)val + descr[i].offset;

			/* Field has been decoded already, skip */
			if (decoded_fields & ((int64_t)1 << i)) {
				continue;
			}

			/* Check if it's the i-th field */
			if (kv.key_len != descr[i].field_name_len) {
				continue;
			}

			if (memcmp(kv.key, descr[i].field_name,
				   descr[i].field_name_len)) {
				continue;
			}

			/* Store the decoded value */
			ret = decode_value(obj, &descr[i], &kv.value,
					   decode_field, val);
			if (ret < 0) {
				return ret;
			}

			decoded_fields |= (int64_t)1 << i;
			break;
		}

		/* Catchall, if an unexpected key is provided in the encoded JSON
		 * object, the parser needs to skip the value for that key.
		 */
		if (i >= descr_len) {
			if (kv.value.type == JSON_TOK_OBJECT_START ||
			    kv.value.type == JSON_TOK_LIST_START) {
				int err = arr_data_parse(obj, &kv.value);

				if (err < 0) {
					return err;
				}
			}
		}
	}

	return -EINVAL;
}

int64_t json_obj_parse(char *payload, size_t len,
		       const struct json_obj_descr *descr, size_t descr_len,
		       void *val)
{
	struct json_obj obj;
	int64_t ret;

	assert(descr_len < (sizeof(ret) * CHAR_BIT - 1));

	ret = obj_init(&obj, payload, len);
	if (ret < 0) {
		return ret;
	}

	return obj_parse(&obj, descr, descr_len, val);
}

int json_arr_separate_object_parse_init(struct json_obj *json, char *payload, size_t len)
{
	struct token tok;

	lexer_init(&json->lex, payload, len);

	lexer_next(&json->lex, &tok);
	if (tok.type != JSON_TOK_LIST_START) {
		return -EINVAL;
	}

	return 0;
}

int json_arr_separate_parse_object(struct json_obj *json, const struct json_obj_descr *descr,
				   size_t descr_len, void *val)
{
	struct token tok;

	if (arr_next(json, &tok) < 0) {
		return -EINVAL;
	}

	if (tok.type == JSON_TOK_LIST_END) {
		return 0;
	}
	if (tok.type != JSON_TOK_OBJECT_START) {
		return -EINVAL;
	}

	return obj_parse(json, descr, descr_len, val);
}

int json_arr_parse(char *payload, size_t len,
		   const struct json_obj_descr *descr, void *val)
{
	struct json_obj arr;
	struct token tok;
	void *ptr = (char *)val + descr->array.element_descr->offset;

	lexer_init(&arr.lex, payload, len);

	lexer_next(&arr.lex, &tok);
	if (tok.type != JSON_TOK_LIST_START) {
		return -EINVAL;
	}

	return decode_value(&arr, descr, &tok, ptr, val);
}

static char escape_as(char chr)
{
	switch (chr) {
	case '"':
		return '"';
	case '\\':
		return '\\';
	case '\b':
		return 'b';
	case '\f':
		return 'f';
	case '\n':
		return 'n';
	case '\r':
		return 'r';
	case '\t':
		return 't';
	}

	return 0;
}

static int json_escape_internal(const char *str,
				json_append_bytes_t append_bytes,
				void *data)
{
	const char *cur;
	int ret = 0;

	for (cur = str; ret == 0 && *cur; cur++) {
		char escaped = escape_as(*cur);

		if (escaped) {
			char bytes[2] = { '\\', escaped };

			ret = append_bytes(bytes, 2, data);
		} else {
			ret = append_bytes(cur, 1, data);
		}
	}

	return ret;
}

size_t json_calc_escaped_len(const char *str, size_t len)
{
	size_t escaped_len = len;
	size_t pos;

	for (pos = 0; pos < len; pos++) {
		if (escape_as(str[pos])) {
			escaped_len++;
		}
	}

	return escaped_len;
}

ssize_t json_escape(char *str, size_t *len, size_t buf_size)
{
	char *next; /* Points after next character to escape. */
	char *dest; /* Points after next place to write escaped character. */
	size_t escaped_len = json_calc_escaped_len(str, *len);

	if (escaped_len == *len) {
		/*
		 * If no escape is necessary, there is nothing to do.
		 */
		return 0;
	}

	if (escaped_len >= buf_size) {
		return -ENOMEM;
	}

	/*
	 * By walking backwards in the buffer from the end positions
	 * of both the original and escaped strings, we avoid using
	 * extra space. Characters in the original string are
	 * overwritten only after they have already been escaped.
	 */
	str[escaped_len] = '\0';
	for (next = &str[*len], dest = &str[escaped_len]; next != str;) {
		char next_c = *(--next);
		char escape = escape_as(next_c);

		if (escape) {
			*(--dest) = escape;
			*(--dest) = '\\';
		} else {
			*(--dest) = next_c;
		}
	}
	*len = escaped_len;

	return 0;
}

static int encode(const struct json_obj_descr *descr, const void *val,
		  json_append_bytes_t append_bytes, void *data);

static int arr_encode(const struct json_obj_descr *elem_descr,
		      const void *field, const void *val,
		      json_append_bytes_t append_bytes, void *data)
{
	ptrdiff_t elem_size;
	/*
	 * NOTE: Since an element descriptor's offset isn't meaningful
	 * (multiple elements occur at multiple offsets in `field'), we
	 * reuse its space in elem_descr to store the offset to the
	 * field containing the number of elements.
	 */
	size_t n_elem = *(size_t *)((char *)val + elem_descr->offset);
	size_t i;
	int ret;

	if (elem_descr->type == JSON_TOK_OBJ_ARRAY) {
		elem_size = elem_descr->field.size;
		elem_descr = elem_descr->object.sub_descr;
	} else {
		elem_size = get_elem_size(elem_descr);
	}

	ret = append_bytes("[", 1, data);
	if (ret < 0) {
		return ret;
	}

	for (i = 0; i < n_elem; i++) {
		/*
		 * Though "field" points at the actual field in "val", the
		 * offset in elem_descr is set to the offset of the
		 * length field in "val", so we have to adjust the
		 * pointer we pass to encode() so that when it adds
		 * elem_descr->offset, it will get the actual element
		 * pointer.
		 */
		const void *ptr = (char *)field + i * elem_size -
			elem_descr->offset;

		ret = encode(elem_descr, ptr, append_bytes, data);
		if (ret < 0) {
			return ret;
		}

		if (i < n_elem - 1) {
			ret = append_bytes(",", 1, data);
			if (ret < 0) {
				return ret;
			}
		}
	}

	return append_bytes("]", 1, data);
}

static int str_encode(const char **str, json_append_bytes_t append_bytes,
		      void *data)
{
	int ret;

	ret = append_bytes("\"", 1, data);
	if (ret < 0) {
		return ret;
	}

	ret = json_escape_internal(*str, append_bytes, data);
	if (!ret) {
		return append_bytes("\"", 1, data);
	}

	return ret;
}

